#!/bin/sh
# Local S3-compatible storage buckets (owner: Ayush; KYC store requirements: Sagar, #39/#96).
# Runs in the amazon/aws-cli image against the SeaweedFS S3 gateway. Buckets are private
# (anonymous reads return 403); objects are reached only through short-lived signed URLs
# generated by the owning service. Sensitive buckets are encrypted at rest with SSE-S3.
set -eu

S3="aws --endpoint-url ${S3_ENDPOINT_URL:-http://s3:8333}"

# The gateway accepts connections a moment before the filer is ready.
attempt=0
until $S3 s3api list-buckets >/dev/null 2>&1; do
  attempt=$((attempt + 1))
  if [ "$attempt" -ge 30 ]; then
    echo "S3 gateway not ready after 60 s" >&2
    exit 1
  fi
  sleep 2
done

for bucket in kyc-documents dispute-evidence listing-images; do
  $S3 s3api head-bucket --bucket "$bucket" >/dev/null 2>&1 || $S3 s3api create-bucket --bucket "$bucket" >/dev/null
  echo "bucket ready: $bucket"
done

for bucket in kyc-documents dispute-evidence; do
  $S3 s3api put-bucket-encryption --bucket "$bucket" --server-side-encryption-configuration \
    '{"Rules":[{"ApplyServerSideEncryptionByDefault":{"SSEAlgorithm":"AES256"}}]}'
  echo "encryption at rest (SSE-S3): $bucket"
done

# Signed-URL-only policy: prove anonymous access is refused, so a leaked object key alone
# never exposes a document. Fails the init container (and so the stack) if a bucket is public.
probe="zeo-private-probe.txt"
for bucket in kyc-documents dispute-evidence; do
  printf 'probe' | $S3 s3 cp - "s3://$bucket/$probe" >/dev/null
  if $S3 --no-sign-request s3api head-object --bucket "$bucket" --key "$probe" >/dev/null 2>&1; then
    echo "bucket $bucket allows anonymous reads; refusing to continue" >&2
    exit 1
  fi
  $S3 s3 rm "s3://$bucket/$probe" >/dev/null
  echo "anonymous read refused: $bucket"
done
